-- Act on the Review Queue sheet of queerguide-unified_tags-2026-10-23_cleaned.xlsx
-- (2,256 rows). The sheet's text corrections for these rows were already applied
-- by 99991792755932; this file handles the review decisions themselves.
--
-- The rows are notes for a person, not machine instructions, so only the part
-- that is unambiguous is applied (decided 2026-10-23):
--
-- 1. MERGES (250 pairs). A "Merge / remove" note that names a single live target
--    ("Merge into X", "Duplicate of X; merge"), stated in one direction only, with
--    no hedging word (consider/likely/probably/check/...) and no chain (neither
--    side is the source or target of another pair). The target the NOTE names is
--    kept, never the more-used side: usage would keep German titles over English
--    ones (kultur 3,132 uses vs arts-culture 10). Pairs the sheet states both
--    ways (youth->jugend AND jugend->youth, 72 of them) are NOT merged.
--    merge_tag_concept moves assignments, tags[] arrays and category rows, mints
--    an alias from the old slug and writes tag_merge_audit, so every merge is
--    reversible with unmerge_tag_concept(audit_id).
--    36 of them have a source carrying approved aliases; merge_tag_concept does
--    not move those, so each merge is followed by repointing the source's
--    aliases at the canonical (see the loop). One clear pair, brats -> brat, is
--    QUEUED instead: e2e/tags-wrong-entity pins that page.
--
-- 2. EVERYTHING ELSE (2,006 rows: 1,233 merge/remove, 577 verify-facts, 196 check)
--    is queued in tag_suggestions with entity_type = 'tag', which the admin inbox's
--    Tags queue renders (as "A ⇄ B" where the note names a target). Approving such
--    a row is refused by approve_tag_suggestions; a reviewer acts on the tag and
--    then rejects the row to dismiss it.

set local statement_timeout = '60min';
select set_config('app.actor', 'migration:99991792781503_tag_review_queue_excel_2026_10_23', true);

-- ---------------------------------------------------------------- 1. merges
create temp table _rm (src text primary key, tgt text not null) on commit drop;

create temp table _rm_pairs on commit drop as
select r.src, r.tgt, s.id as src_id, t.id as tgt_id
from _rm r
join public.unified_tags s on s.slug = r.src and s.status = 'active'
join public.unified_tags t on t.slug = r.tgt and t.status = 'active'
where s.id <> t.id
  and not exists (select 1 from public.tag_relationship_exclusions e
                  where e.tag1_id = least(s.id, t.id) and e.tag2_id = greatest(s.id, t.id))
  -- zy_validate_tag_entity_target re-checks a redirect row on every update, and
  -- the merge updates both sides; skip a pair whose redirect target is missing.
  and not exists (select 1 from public.unified_tags u
                  where u.id in (s.id, t.id) and u.publication_role = 'entity_redirect'
                    and (case u.canonical_entity_type
    when 'personality' then (select '/personalities/'||x.slug from public.personalities x where x.id=u.canonical_entity_id and x.duplicate_of_id is null)
    when 'city' then (select '/city/'||x.slug from public.cities x where x.id=u.canonical_entity_id and x.duplicate_of_id is null)
    when 'country' then (select '/country/'||x.slug from public.countries x where x.id=u.canonical_entity_id and x.duplicate_of_id is null)
    when 'village' then (select '/villages/'||x.slug from public.queer_villages x where x.id=u.canonical_entity_id and x.duplicate_of_id is null)
    when 'venue' then (select '/venues/'||x.slug from public.venues x where x.id=u.canonical_entity_id and x.duplicate_of_id is null)
    when 'organization' then (select '/organizations/'||x.slug from public.organizations x where x.id=u.canonical_entity_id and x.duplicate_of_id is null)
    when 'event' then (select '/events/'||x.slug from public.events x where x.id=u.canonical_entity_id and x.duplicate_of_id is null)
    when 'hotel' then (select '/hotels/'||x.slug from public.hotels x where x.id=u.canonical_entity_id and x.duplicate_of_id is null)
    when 'community_group' then (select '/groups/'||x.id::text from public.community_groups x where x.id=u.canonical_entity_id and x.duplicate_of_id is null)
  end) is distinct from u.canonical_entity_path);

-- merge_tag_concept's trigger (log_unified_tag_merge_redirect) inserts into the
-- serial tag_slug_redirects. A restored copy of the table can carry rows above
-- its sequence (the CI snapshot does: 148 of 214 merges hit tag_slug_redirects_pkey),
-- so move the sequence up to max(id) first. It never moves backwards, so on a
-- database whose sequence is already ahead this is a no-op.
select setval('public.tag_slug_redirects_id_seq',
              greatest((select coalesce(max(id), 1) from public.tag_slug_redirects),
                       (select last_value from public.tag_slug_redirects_id_seq)));

-- pap-smear still carries a non-primary "Events & Parties" membership from its
-- old misfiling; the merge would carry it onto the Pap test, and /tags lists a
-- tag under every category it belongs to. Drop that one row first.
delete from public.tag_category_assignments j
 using public.unified_tags t, public.tag_categories c
 where j.tag_id = t.id and t.slug = 'pap-smear' and t.status = 'active'
   and j.category_id = c.id and c.name = 'Events & Parties' and not j.is_primary;

create temp table _rm_done (src_id uuid, tgt_id uuid, audit_id uuid, err text) on commit drop;

do $merge$
declare r record; v_audit uuid;
begin
  for r in select * from _rm_pairs order by src loop
    begin
      -- The duplicate's primary category row would collide with the canonical's
      -- primary (one_primary_per_tag) when merge_tag_concept moves it across.
      update public.tag_category_assignments set is_primary = false
       where tag_id = r.src_id and is_primary;
      v_audit := public.merge_tag_concept(r.tgt_id, r.src_id,
                   'migration:99991792781503', 'excel-review-2026-10-23');
      -- merge_tag_concept mints an alias from the old slug but leaves the
      -- duplicate's EXISTING aliases on the merged row, where they route to a
      -- tag nobody can open. Repoint them at the canonical. This runs after the
      -- merge on purpose: tag_alias_reject_shadow refuses an alias whose slug is
      -- a live tag other than its own canonical, and before the merge the
      -- source is still live. An alias that would only repeat the canonical's
      -- own name is junk on the canonical (alias_equals_name), so it is dropped.
      delete from public.tag_aliases a
       using public.unified_tags c
       where a.canonical_tag_id = r.src_id and c.id = r.tgt_id
         and lower(btrim(a.alias_name)) = lower(btrim(c.name));
      update public.tag_aliases set canonical_tag_id = r.tgt_id
       where canonical_tag_id = r.src_id;
    exception when others then
      raise notice 'review merge skipped % -> %: %', r.src, r.tgt, sqlerrm;
    end;
  end loop;
end
$merge$;

do $verify_merges$
declare v_sheet int; v_eligible int; v_ok int; v_err int; v_bad int;
begin
  select count(*) into v_sheet from _rm;
  select count(*) into v_eligible from _rm_pairs;
  select count(*) filter (where audit_id is not null), count(*) filter (where audit_id is null)
    into v_ok, v_err from _rm_done;
  select count(*) into v_bad
  from _rm_done d join public.unified_tags s on s.id = d.src_id
  where d.audit_id is not null and (s.status <> 'merged' or s.merged_into_id is null);
  raise notice 'review merges: % pairs in sheet, % eligible, % merged, % failed', v_sheet, v_eligible, v_ok, v_err;
  if v_bad <> 0 then
    raise exception 'review merges: % merged sources are not status=merged', v_bad;
  end if;
  select count(*) into v_bad
  from _rm_done d join public.tag_aliases a on a.canonical_tag_id = d.src_id
  where d.audit_id is not null;
  if v_bad <> 0 then
    raise exception 'review merges: % aliases still point at a merged source', v_bad;
  end if;
  if v_err > greatest(5, v_eligible * 0.05) then
    raise exception 'review merges: % of % eligible merges failed', v_err, v_eligible;
  end if;
  if v_eligible < v_sheet * 0.8 then
    raise exception 'review merges: only % of % pairs were eligible; the corpus has drifted from the export', v_eligible, v_sheet;
  end if;
end
$verify_merges$;

-- pubic-lice was human-reviewed (verification_status 'reviewed'); its merge
-- target pubic-lice-crabs is is_sensitive and only 'auto', so without this the
-- Pubic lice page would become sign-in-only for anon (tag_is_anon_gated).
-- Carry the review across, decided 2026-10-23. Copied from the source row, so
-- it does nothing if the source was never reviewed.
update public.unified_tags c
   set verification_status = s.verification_status
  from public.unified_tags s
 where c.slug = 'pubic-lice-crabs' and c.status = 'active'
   and s.slug = 'pubic-lice' and s.merged_into_id = c.id
   and s.verification_status in ('reviewed', 'locked')
   and c.verification_status is distinct from s.verification_status;

do $verify_review$
declare v_bad int;
begin
  select count(*) into v_bad
  from public.unified_tags s join public.unified_tags c on c.id = s.merged_into_id
  where s.slug = 'pubic-lice' and c.slug = 'pubic-lice-crabs'
    and s.verification_status in ('reviewed', 'locked')
    and c.verification_status is distinct from s.verification_status;
  if v_bad <> 0 then
    raise exception 'pubic-lice-crabs did not inherit the reviewed status of pubic-lice';
  end if;
end
$verify_review$;

-- ---------------------------------------------------------------- 2. queue
create temp table _rq (slug text primary key, target text, review_type text, label text, note text, qa text) on commit drop;

select t.id, 'tag', g.id, r.label, 'excel_review_2026_10_23', 'pending', r.note,
       jsonb_build_object('review_type', r.review_type, 'qa_issues', r.qa,
                          'suggested_target', r.target, 'sheet', 'queerguide-unified_tags-2026-10-23_cleaned.xlsx')
from _rq r
join public.unified_tags t on t.slug = r.slug and t.status <> 'merged'
left join public.unified_tags g on g.slug = r.target and g.status = 'active' and g.id <> t.id
on conflict (entity_id, entity_type, suggested_tag_name) do nothing;

do $verify_queue$
declare v_rows int; v_present int; v_queued int;
begin
  select count(*) into v_rows from _rq;
  select count(*) into v_present from _rq r join public.unified_tags t on t.slug = r.slug and t.status <> 'merged';
  select count(*) into v_queued from public.tag_suggestions s
   where s.source = 'excel_review_2026_10_23' and s.entity_type = 'tag' and s.status = 'pending';
  raise notice 'review queue: % rows in sheet, % tags present, % pending review items', v_rows, v_present, v_queued;
  if v_queued < v_present then
    raise exception 'review queue: only % of % present tags were queued', v_queued, v_present;
  end if;
end
$verify_queue$;
